/**
 * Drizzle schema of JSVola. Every table carries the `vola_` prefix; ids are UUID v7
 * (`uuidv7()`, generated by the application). `pnpm db:generate` writes the migrations into
 * `../../drizzle`.
 */
import { type SQL, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  customType,
  index,
  integer,
  jsonb,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from "drizzle-orm/pg-core";
import { uuidv7 } from "./uuid.js";

const id = () => uuid("id").primaryKey().$defaultFn(uuidv7);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});
const tsvector = customType<{ data: string; driverData: string }>({
  dataType: () => "tsvector",
});

/**
 * How many characters of `ocr_text` feed `ocr_tsv`: a tsvector may not exceed 1 MB, and the
 * OCR of a 20-page scan is far below this cut.
 */
export const OCR_TSV_MAX_CHARS = 500_000;

/** A tenant: every file, folder and (non-admin) API key belongs to exactly one. */
export const tenants = pgTable(
  "vola_tenant",
  {
    id: id(),
    /** Stable identifier (`^[a-z0-9][a-z0-9-]{1,62}$`); `X-Tenant-Slug` of admin requests. */
    slug: varchar("slug", { length: 64 }).notNull().unique(),
    name: varchar("name", { length: 200 }).notNull(),
    /** Inactive: every key of the tenant fails authentication. */
    isActive: boolean("is_active").notNull().default(true),
    /**
     * The encryption of an upload that names none (`none` | `tenant` | `keyring`; `vola
     * tenant-set --default-encryption`). `caller` is in the CHECK for phase 6.3.
     */
    defaultEncryption: varchar("default_encryption", { length: 16 }).notNull().default("none"),
    createdAt: createdAt(),
  },
  (t) => [
    check(
      "vola_tenant_default_encryption_check",
      sql`${t.defaultEncryption} in ('none', 'tenant', 'keyring', 'caller')`,
    ),
  ],
);

/**
 * API keys. Only the SHA-256 of the plaintext is stored; `prefix` + `last4` identify a key
 * to a person (`vola_live…k3Qz`). `tenant_id` NULL ⇔ `is_admin`: a cross-tenant admin key.
 */
export const apiKeys = pgTable(
  "vola_apikey",
  {
    id: id(),
    tenantId: uuid("tenant_id").references(() => tenants.id, { onDelete: "cascade" }),
    name: varchar("name", { length: 200 }).notNull(),
    /** SHA-256 of the plaintext key, lowercase hex. */
    keyHash: varchar("key_hash", { length: 64 }).notNull().unique(),
    /** `vola_live` | `vola_test` | `vola_admin`. */
    prefix: varchar("prefix", { length: 16 }).notNull(),
    last4: varchar("last4", { length: 4 }).notNull(),
    scopes: text("scopes").array().notNull(),
    isAdmin: boolean("is_admin").notNull().default(false),
    createdAt: createdAt(),
    /** Updated at most once a minute per key. */
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    /** Soft revoke: the row stays, authentication fails. */
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    /** Who created it: the `X-User-Id` of the request, a CLI user name, … */
    createdBy: varchar("created_by", { length: 255 }),
  },
  (t) => [
    index("vola_apikey_tenant_idx").on(t.tenantId),
    check("vola_apikey_prefix_check", sql`${t.prefix} in ('vola_live', 'vola_test', 'vola_admin')`),
    check("vola_apikey_admin_check", sql`(${t.tenantId} is null) = ${t.isAdmin}`),
  ],
);

/**
 * A virtual folder inside `(tenant, instance_type, instance_id)`: the hierarchy lives only in
 * the database (the blob store is flat). `path` is the full normalised path `a/b/c` — no
 * leading or trailing `/` — and is what lookups use (one SELECT, no walk); `parent_id` gives
 * the tree. A rename or move rewrites the `path` of every descendant in one transaction.
 * Soft delete keeps the row; the partial unique index lets the path be created again.
 * `default_keyring_id` is the folder's encryption policy (6.2): every new upload into it or
 * below it is encrypted under that keyring; NULL means no policy of its own.
 */
export const folders = pgTable(
  "vola_folder",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    instanceType: varchar("instance_type", { length: 100 }).notNull(),
    instanceId: uuid("instance_id").notNull(),
    /** NULL: a top-level folder. */
    parentId: uuid("parent_id").references((): AnyPgColumn => folders.id, {
      onDelete: "cascade",
    }),
    /** The last segment of `path`. */
    name: varchar("name", { length: 255 }).notNull(),
    /** `a/b/c`: at most FOLDER_MAX_DEPTH segments of at most 255 characters. */
    path: text("path").notNull(),
    defaultKeyringId: uuid("default_keyring_id"),
    createdBy: varchar("created_by", { length: 255 }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    deletedBy: varchar("deleted_by", { length: 255 }),
  },
  (t) => [
    uniqueIndex("vola_folder_path_live_uq")
      .on(t.tenantId, t.instanceType, t.instanceId, t.path)
      .where(sql`${t.deletedAt} is null`),
    index("vola_folder_parent_idx").on(t.tenantId, t.instanceType, t.instanceId, t.parentId),
    check("vola_folder_instance_type_check", sql`${t.instanceType} ~ '^[a-z][a-z0-9_]*$'`),
    check("vola_folder_path_check", sql`${t.path} <> '' and ${t.path} !~ '(^/|/$|//)'`),
  ],
);

/**
 * A stored file: one row per upload, pointing at a content-addressable blob by `hash` (many
 * rows, of any tenant, may share one blob). Every row belongs to `(tenant, instance_type,
 * instance_id)` — the host application's object the file is attached to. Soft delete keeps the
 * row (`deleted_at`); purge removes it, and the blob when nothing references it any more.
 *
 * Encryption (phase 6, `docs/CRYPTO.md`): for `encryption != none` the row holds `enc_format`
 * (the `JSV` version of the blob), `fk_ct` (the wrapped file key — the only way to the bytes;
 * deleting the row is a crypto-shred) and `meta_ct` (name, MIME type and metadata, sealed
 * under the file key), while `filename` is `<id>.bin`, `mime_type` `application/octet-stream`,
 * `extension` NULL, `kind` `other`, `metadata` `{}`; `size` is the PLAINTEXT length (quotas
 * and the UI count what the user stored, not the 16 B per segment of GCM tags) and `hash` is
 * the SHA-256 of the CIPHERTEXT (the plaintext hash is never stored). `keyring_id` names the
 * `vola_keyring` whose master key wraps `fk_ct` of a `keyring` file (6.2); NULL otherwise. A
 * `caller` file's `fk_ct` is under the key the caller sends with every request, a `client`
 * file's `fk_ct` and `meta_ct` are whatever the client handed over (6.3): the server opens
 * neither.
 * `folder_id` (NULL: the instance root) points at a `vola_folder`; `parent_id` at the
 * previous version of the same file (the chain `GET …/versions` walks).
 */
export const files = pgTable(
  "vola_file",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    /** `^[a-z][a-z0-9_]*$`, e.g. `tickets`. */
    instanceType: varchar("instance_type", { length: 100 }).notNull(),
    instanceId: uuid("instance_id").notNull(),
    /** Named file inside the instance (`avatar`): at most one LIVE row per slug. */
    slug: varchar("slug", { length: 100 }),
    /** SHA-256 hex of the stored bytes. */
    hash: varchar("hash", { length: 64 }).notNull(),
    size: bigint("size", { mode: "number" }).notNull(),
    /** As uploaded, after the collision rename (`a (1).pdf`). */
    filename: varchar("filename", { length: 255 }).notNull(),
    /** Lowercase, without the dot; NULL when the name has none. */
    extension: varchar("extension", { length: 50 }),
    mimeType: varchar("mime_type", { length: 255 }).notNull(),
    /** `image` | `document` | … | `other` (FileKinds). */
    kind: varchar("kind", { length: 20 }).notNull(),
    metadata: jsonb("metadata").$type<Record<string, unknown>>().notNull().default({}),
    folderId: uuid("folder_id").references(() => folders.id, { onDelete: "set null" }),
    parentId: uuid("parent_id").references((): AnyPgColumn => files.id, {
      onDelete: "set null",
    }),
    isPublic: boolean("is_public").notNull().default(false),
    isGlobalPublic: boolean("is_global_public").notNull().default(false),
    /** `none` | `tenant` | `keyring` | `caller` | `client`. */
    encryption: varchar("encryption", { length: 16 }).notNull().default("none"),
    encFormat: smallint("enc_format"),
    keyringId: uuid("keyring_id"),
    /** The wrapped per-file key. */
    fkCt: bytea("fk_ct"),
    /** Encrypted metadata (name, MIME) of an encrypted file. */
    metaCt: bytea("meta_ct"),
    createdBy: varchar("created_by", { length: 255 }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    deletedBy: varchar("deleted_by", { length: 255 }),
    /** Written at most once a minute per file, by GET downloads only. */
    lastAccessedAt: timestamp("last_accessed_at", { withTimezone: true }),
    lastAccessedBy: varchar("last_accessed_by", { length: 255 }),
  },
  (t) => [
    index("vola_file_instance_idx").on(t.tenantId, t.instanceType, t.instanceId),
    index("vola_file_hash_idx").on(t.hash),
    index("vola_file_folder_idx").on(t.folderId),
    index("vola_file_parent_idx").on(t.parentId),
    index("vola_file_keyring_idx").on(t.keyringId),
    uniqueIndex("vola_file_slug_live_uq")
      .on(t.tenantId, t.instanceType, t.instanceId, t.slug)
      .where(sql`${t.deletedAt} is null and ${t.slug} is not null`),
    check("vola_file_instance_type_check", sql`${t.instanceType} ~ '^[a-z][a-z0-9_]*$'`),
    check("vola_file_hash_check", sql`${t.hash} ~ '^[a-f0-9]{64}$'`),
    check("vola_file_size_check", sql`${t.size} >= 0`),
    check(
      "vola_file_encryption_check",
      sql`${t.encryption} in ('none', 'tenant', 'keyring', 'caller', 'client')`,
    ),
  ],
);

/**
 * A resumable upload in flight (tus 1.0 core: `POST|HEAD|PATCH|DELETE /uploads`). The bytes
 * received so far sit in `<storage>/uploads/<id>.part`; `offset` is how many of them are
 * durable (committed only after `fsync`). When `offset` reaches `length` the part file goes
 * through the same `finalizeUpload` as a plain `POST /files` and `completed_file_id` points at
 * the row it became. An upload belongs to the TENANT (any `files:write` key of it may resume
 * it); `api_key_id` only records which key created it. Rows past `expires_at` are swept with
 * their part files. `encryption` is decided at creation (NULL in rows from before phase 6.1
 * means `none`); for anything but `none` the part file is the `JSV` blob from its first byte
 * and `enc_state` (`services/upload-crypto.ts`) holds what sealing the next segment needs —
 * the future file id, the wrapped key, the nonce prefix, the segment size, how many segments
 * are sealed, the sealed tail's size and nonce counter, the running hash and the sealed
 * sniffing head; for `client` only the file id and the records the client handed over.
 */
export const uploads = pgTable(
  "vola_upload",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    apiKeyId: uuid("api_key_id").references(() => apiKeys.id, { onDelete: "set null" }),
    instanceType: varchar("instance_type", { length: 100 }).notNull(),
    instanceId: uuid("instance_id").notNull(),
    /** Normalised folder path given at creation; resolved (created when missing) at completion. */
    folderPath: text("folder_path"),
    folderId: uuid("folder_id").references(() => folders.id, { onDelete: "set null" }),
    /** The version this upload supersedes. */
    parentId: uuid("parent_id").references(() => files.id, { onDelete: "set null" }),
    slug: varchar("slug", { length: 100 }),
    filename: varchar("filename", { length: 255 }).notNull(),
    declaredMime: varchar("declared_mime", { length: 255 }),
    metadata: jsonb("metadata").$type<Record<string, unknown>>().notNull().default({}),
    /** `Upload-Length`: known at creation (`Upload-Defer-Length` is not supported). */
    length: bigint("length", { mode: "number" }).notNull(),
    /** Bytes durably on disk. */
    offset: bigint("offset", { mode: "number" }).notNull().default(0),
    createdBy: varchar("created_by", { length: 255 }),
    createdAt: createdAt(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    completedFileId: uuid("completed_file_id").references(() => files.id, {
      onDelete: "set null",
    }),
    /** `none` | `tenant` | `keyring` | `caller` | `client`; NULL in old rows = `none`. */
    encryption: varchar("encryption", { length: 16 }),
    /** The segment cipher state of an encrypted upload (`EncState` / `ClientEncState`); NULL for a plain one. */
    encState: jsonb("enc_state").$type<Record<string, unknown>>(),
  },
  (t) => [
    index("vola_upload_tenant_idx").on(t.tenantId),
    index("vola_upload_expires_idx").on(t.expiresAt),
    check("vola_upload_instance_type_check", sql`${t.instanceType} ~ '^[a-z][a-z0-9_]*$'`),
    check("vola_upload_length_check", sql`${t.length} >= 0`),
    check("vola_upload_offset_check", sql`${t.offset} >= 0 and ${t.offset} <= ${t.length}`),
  ],
);

/**
 * One unit of background work on a file (plan 4.1): a thumbnail of one size and crop, an
 * OCR pass (4.2). `params` tells the jobs of one `kind` apart (`{size, crop}` for a
 * thumbnail) and `(file, kind, params)` is unique: asking for the same thumbnail twice
 * refreshes the row instead of adding one. `status` walks PENDING → RUNNING → DONE | FAILED
 * (after `attempts` tries); `SKIPPED` is reserved for a job that was deliberately not run.
 * `error` is a short reason without the file name. The aggregate of a file's rows is its
 * `processing_status` (`aggregateProcessingStatus` in `@vola/core`). Rows go with the file.
 */
export const processingJobs = pgTable(
  "vola_processing_job",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    fileId: uuid("file_id")
      .notNull()
      .references(() => files.id, { onDelete: "cascade" }),
    /** `THUMBNAIL` | `OCR` (ProcessingKinds). */
    kind: varchar("kind", { length: 20 }).notNull(),
    params: jsonb("params").$type<Record<string, unknown>>().notNull().default({}),
    /** `PENDING` | `RUNNING` | `DONE` | `FAILED` | `SKIPPED` (ProcessingStatuses). */
    status: varchar("status", { length: 20 }).notNull().default("PENDING"),
    /** Tries so far (the worker gives up after 3). */
    attempts: smallint("attempts").notNull().default(0),
    /** Why the last try failed, briefly; never the file name. */
    error: varchar("error", { length: 500 }),
    createdAt: createdAt(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("vola_processing_job_identity_uq").on(t.fileId, t.kind, t.params),
    index("vola_processing_job_tenant_status_idx").on(t.tenantId, t.status),
    check("vola_processing_job_kind_check", sql`${t.kind} in ('THUMBNAIL', 'OCR')`),
    check(
      "vola_processing_job_status_check",
      sql`${t.status} in ('PENDING', 'RUNNING', 'DONE', 'FAILED', 'SKIPPED')`,
    ),
    check("vola_processing_job_attempts_check", sql`${t.attempts} >= 0`),
  ],
);

/**
 * Sidecar of a file for what the worker extracted (plan 4.2): the OCR text of an image or a
 * PDF (`tesseract`), the language set it ran with (`eng+srp+deu`), how many pages were read
 * and when. `ocr_tsv` is generated from the text (`simple` configuration: no stemming, every
 * language alike) and GIN-indexed for the `ocr` filter of the UDC `files` collection
 * (`plainto_tsquery('simple', …)`). One row per file, gone with the file. An ENCRYPTED file
 * (phase 6.3) keeps its result sealed under the file key in `ocr_ct` — text, language and
 * page count together — while `ocr_text`, `ocr_lang` and `ocr_pages` stay NULL: `ocr_tsv` is
 * then empty and the file is not in the full-text search (`docs/CRYPTO.md` § 11).
 */
export const fileMetadata = pgTable(
  "vola_file_metadata",
  {
    fileId: uuid("file_id")
      .primaryKey()
      .references(() => files.id, { onDelete: "cascade" }),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    /** Pages joined with `\f`; NULL until an OCR pass stored something. */
    ocrText: text("ocr_text"),
    /** The `-l` tesseract ran with (`eng+srp+deu`). */
    ocrLang: varchar("ocr_lang", { length: 64 }),
    /** Pages read (1 for an image; at most VOLA_OCR_MAX_PAGES of a PDF). */
    ocrPages: integer("ocr_pages"),
    ocrAt: timestamp("ocr_at", { withTimezone: true }),
    /** Phase 6.3: `nonce ∥ AES-GCM(FK, {v, text, lang, pages}, "<file id>:ocr")` of an encrypted file. */
    ocrCt: bytea("ocr_ct"),
    ocrTsv: tsvector("ocr_tsv").generatedAlwaysAs(
      (): SQL =>
        sql`to_tsvector('simple', left(coalesce(ocr_text, ''), ${sql.raw(String(OCR_TSV_MAX_CHARS))}))`,
    ),
  },
  (t) => [
    index("vola_file_metadata_tenant_idx").on(t.tenantId),
    index("vola_file_metadata_ocr_tsv_idx").using("gin", t.ocrTsv),
    check("vola_file_metadata_ocr_pages_check", sql`${t.ocrPages} is null or ${t.ocrPages} >= 0`),
  ],
);

/**
 * A share link (plan 5.1): anonymous access to one file or one folder of a tenant through an
 * opaque token. Only the SHA-256 of the token is stored (`token_hash`); the plaintext is
 * returned once, at creation. Exactly one of `file_id` / `folder_id` is set (the XOR check).
 * `scope` is a `ShareScopes` term — v1 implements `PUBLIC_LINK` only. `password_hash` is an
 * argon2id string; `expires_at`, `max_downloads` / `download_count` and `revoked_at` decide
 * whether the link still answers (`410 share_gone` otherwise). `fk_share_ct` is reserved for
 * the share grant of an encrypted file (plan 6.3): the file key wrapped under the link's
 * secret; NULL until then.
 */
export const shareLinks = pgTable(
  "vola_share_link",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    fileId: uuid("file_id").references(() => files.id, { onDelete: "cascade" }),
    folderId: uuid("folder_id").references(() => folders.id, { onDelete: "cascade" }),
    /** SHA-256 of the plaintext token (32 random bytes, base64url), lowercase hex. */
    tokenHash: varchar("token_hash", { length: 64 }).notNull().unique(),
    /** `PUBLIC_LINK` | `TENANT` | `INSTANCE_VIEWERS` | `EMAIL` (ShareScopes); v1: `PUBLIC_LINK`. */
    scope: varchar("scope", { length: 20 }).notNull().default("PUBLIC_LINK"),
    /** argon2id encoded hash (`$argon2id$v=19$m=…`); NULL: no password. */
    passwordHash: text("password_hash"),
    /** NULL: never expires. */
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    /** NULL: unlimited. Only a request that STARTS a download counts (not HEAD, not a Range continuation). */
    maxDownloads: integer("max_downloads"),
    downloadCount: integer("download_count").notNull().default(0),
    createdBy: varchar("created_by", { length: 255 }),
    createdAt: createdAt(),
    /** Soft revoke: the row stays, the link answers `410 share_gone`. */
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    /** Phase 6.3: the file key wrapped under the link secret. NULL until then. */
    fkShareCt: bytea("fk_share_ct"),
  },
  (t) => [
    index("vola_share_link_tenant_idx").on(t.tenantId),
    index("vola_share_link_file_idx").on(t.fileId),
    index("vola_share_link_folder_idx").on(t.folderId),
    check("vola_share_link_target_check", sql`(${t.fileId} is null) <> (${t.folderId} is null)`),
    check(
      "vola_share_link_scope_check",
      sql`${t.scope} in ('PUBLIC_LINK', 'TENANT', 'INSTANCE_VIEWERS', 'EMAIL')`,
    ),
    check(
      "vola_share_link_max_downloads_check",
      sql`${t.maxDownloads} is null or ${t.maxDownloads} > 0`,
    ),
    check("vola_share_link_download_count_check", sql`${t.downloadCount} >= 0`),
  ],
);

/**
 * A statistics snapshot (plan 5.1): the live files of a tenant (`scope = tenant`) or of one
 * of its instances (`scope = instance`, `instance_type` + `instance_id` set) — how many, how
 * many bytes (the sum of `size`, before deduplication), how many of each `kind`, the oldest
 * and newest `created_at`. Computed lazily on the first read, on `?recompute=1`, and by the
 * worker's `refresh-stats` job for snapshots older than `VOLA_STATS_TTL_MIN` whose tenant
 * had activity since. Soft-deleted files are never counted. One row per `(tenant, scope,
 * instance)`; rows go with the tenant.
 */
export const tenantStats = pgTable(
  "vola_tenant_stats",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    /** `tenant` | `instance`. */
    scope: varchar("scope", { length: 10 }).notNull(),
    instanceType: varchar("instance_type", { length: 100 }),
    instanceId: uuid("instance_id"),
    totalFiles: bigint("total_files", { mode: "number" }).notNull().default(0),
    totalBytes: bigint("total_bytes", { mode: "number" }).notNull().default(0),
    /** `{ "image": 12, "document": 5 }` — live files per `kind`. */
    byKind: jsonb("by_kind").$type<Record<string, number>>().notNull().default({}),
    oldestAt: timestamp("oldest_at", { withTimezone: true }),
    newestAt: timestamp("newest_at", { withTimezone: true }),
    computedAt: timestamp("computed_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("vola_tenant_stats_tenant_uq").on(t.tenantId).where(sql`${t.scope} = 'tenant'`),
    uniqueIndex("vola_tenant_stats_instance_uq")
      .on(t.tenantId, t.instanceType, t.instanceId)
      .where(sql`${t.scope} = 'instance'`),
    index("vola_tenant_stats_computed_idx").on(t.computedAt),
    check("vola_tenant_stats_scope_check", sql`${t.scope} in ('tenant', 'instance')`),
    check(
      "vola_tenant_stats_instance_check",
      sql`(${t.scope} = 'tenant' and ${t.instanceType} is null and ${t.instanceId} is null) or (${t.scope} = 'instance' and ${t.instanceType} is not null and ${t.instanceId} is not null)`,
    ),
    check("vola_tenant_stats_totals_check", sql`${t.totalFiles} >= 0 and ${t.totalBytes} >= 0`),
  ],
);

/**
 * The Argon2id parameters of one keyring, written at setup and read at every unlock
 * (`crypto/keyring.ts`): raising the cost changes only new wraps, never needs a migration.
 * `salt` is standard base64 of 16 bytes; `pepper_line` is the `kid` (hex) of the pepper line
 * the PIN wrap was last made with — a hint which line to try first, never a secret.
 */
export interface KeyringKdf {
  alg: "argon2id";
  salt: string;
  m: number;
  t: number;
  p: number;
  pepper_line: string;
}

/**
 * A keyring (plan 6.2, `docs/CRYPTO.md` § keyring): one per `(tenant, principal)` — the
 * principal is the `X-User-Id` of the host application. Holds the master key (MK) twice
 * wrapped and nothing else: `mk_pin_ct` under Argon2id(PIN, salt, pepper), `mk_recovery_ct`
 * under Argon2id(recovery key, recovery_salt, pepper); both `nonce ∥ ct ∥ tag` with the AAD
 * `<keyring id>:mk:pin` / `<keyring id>:mk:recovery`. The PIN, the recovery key and the MK
 * are never stored. `attempts` and `locked_until` are the brute-force state (they survive a
 * restart). A reset soft-deletes the row after the crypto-shred of every file under it; the
 * partial unique index lets the principal set up a new one.
 */
export const keyrings = pgTable(
  "vola_keyring",
  {
    id: id(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id, { onDelete: "cascade" }),
    /** The `X-User-Id` that owns it. */
    principal: varchar("principal", { length: 255 }).notNull(),
    kdf: jsonb("kdf").$type<KeyringKdf>().notNull(),
    /** MK under the PIN-derived key. */
    mkPinCt: bytea("mk_pin_ct").notNull(),
    /** MK under the recovery-key-derived key. */
    mkRecoveryCt: bytea("mk_recovery_ct").notNull(),
    /** 16 random bytes: the Argon2 salt of the recovery key (same m/t/p as `kdf`). */
    recoverySalt: bytea("recovery_salt").notNull(),
    /** Wrong PINs in a row; 0 after a right one. */
    attempts: integer("attempts").notNull().default(0),
    /** Until when every PIN — the right one too — is refused (`429`). */
    lockedUntil: timestamp("locked_until", { withTimezone: true }),
    pinSetAt: timestamp("pin_set_at", { withTimezone: true }).notNull().defaultNow(),
    createdAt: createdAt(),
    /** Set by a reset; the files under it are gone by then. */
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("vola_keyring_principal_live_uq")
      .on(t.tenantId, t.principal)
      .where(sql`${t.deletedAt} is null`),
    check("vola_keyring_attempts_check", sql`${t.attempts} >= 0`),
  ],
);

export type TenantRow = typeof tenants.$inferSelect;
export type ApiKeyRow = typeof apiKeys.$inferSelect;
export type FileRow = typeof files.$inferSelect;
export type FolderRow = typeof folders.$inferSelect;
export type UploadRow = typeof uploads.$inferSelect;
export type ProcessingJobRow = typeof processingJobs.$inferSelect;
export type FileMetadataRow = typeof fileMetadata.$inferSelect;
export type ShareLinkRow = typeof shareLinks.$inferSelect;
export type TenantStatsRow = typeof tenantStats.$inferSelect;
export type KeyringRow = typeof keyrings.$inferSelect;
